package com.foodie.order;import com.foodie.order.OrderManager.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api") class OrderController{private final OrderManager service;OrderController(OrderManager s){service=s;}@PostMapping("/orders") ResponseEntity<OrderView> create(@RequestBody CreateRequest x){return ResponseEntity.status(201).body(service.create(x));}@GetMapping("/orders/{id}") OrderView get(@PathVariable Long id){return service.get(id);}@GetMapping("/customers/{id}/cart") CartView cart(@PathVariable Long id){return service.cart(id);}@PostMapping("/customers/{id}/cart/items") CartView add(@PathVariable Long id,@RequestBody LineRequest x){return service.add(id,x);}@DeleteMapping("/customers/{id}/cart") ResponseEntity<Void> clear(@PathVariable Long id){service.clear(id);return ResponseEntity.noContent().build();}}
